ALTER TABLE users ADD COLUMN IF NOT EXISTS reporting_manager_id int REFERENCES users(id) ON DELETE SET NULL;
DO $$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'users_manager_not_self') THEN ALTER TABLE users ADD CONSTRAINT users_manager_not_self CHECK (reporting_manager_id IS NULL OR reporting_manager_id <> id); END IF; END $$;
CREATE INDEX IF NOT EXISTS users_reporting_manager ON users (reporting_manager_id);
-- ITH-109: reporting manager on users; preconfigured service-request workflows approved by the requester's reporting manager.
-- Published v1, DISABLED: an ITSM Admin enables the ones to use (Workflow Designer). Re-running skips names that already exist.
INSERT INTO itsm_workflows (ticket_type, name, description, match, rank, is_active, created_by, updated_by)
SELECT 'request', 'Email / user ID creation (manager approval)', 'Account Setup and Email Setup requests (new email ID, new user ID, shared mailbox, distribution list): the requester''s reporting manager approves, then IT creates it and the requester is told.', '{"category": ["Account Setup", "Email Setup"]}'::jsonb, 5, false, 'System (preconfigured)', 'System (preconfigured)'
WHERE NOT EXISTS (SELECT 1 FROM itsm_workflows WHERE ticket_type = 'request' AND lower(name) = lower('Email / user ID creation (manager approval)'));
INSERT INTO itsm_workflow_versions (workflow_id, version, status, definition, notes, created_by, updated_by, published_by, published_at)
SELECT w.id, 1, 'Published', '{"nodes": [{"id": "s", "type": "start", "label": "Raised", "x": 40, "y": 240, "config": {}}, {"id": "m", "type": "approval", "label": "Reporting manager approval", "x": 240, "y": 240, "config": {"approverType": "reporting_manager", "title": "Manager approval for {no}"}}, {"id": "nrej", "type": "notify", "label": "Tell requester: rejected", "x": 460, "y": 420, "config": {"to": ["requester"], "title": "{no} not approved", "message": "{no}: {title} was not approved."}}, {"id": "rej", "type": "end", "label": "Rejected", "x": 680, "y": 420, "config": {"status": "Rejected"}}, {"id": "nok", "type": "notify", "label": "Tell requester: approved", "x": 460, "y": 240, "config": {"to": ["requester", "team"], "title": "{no} approved", "message": "{no}: {title} was approved by the reporting manager - IT will set it up."}}, {"id": "w", "type": "stage", "label": "IT creating", "x": 680, "y": 240, "config": {"status": "In Progress", "timeoutHours": 24}}, {"id": "rem", "type": "notify", "label": "Remind team", "x": 680, "y": 60, "config": {"to": ["team"], "title": "{no} pending", "message": "{no}: {title} approved more than a day ago and not completed."}}, {"id": "h", "type": "stage", "label": "On hold", "x": 900, "y": 420, "config": {"status": "On Hold"}}, {"id": "done", "type": "stage", "label": "Completed", "x": 900, "y": 240, "config": {"status": "Completed"}}, {"id": "nd", "type": "notify", "label": "Tell requester: ready", "x": 1120, "y": 240, "config": {"to": ["requester"], "title": "{no} ready", "message": "{no}: {title} is ready."}}, {"id": "end", "type": "end", "label": "Done", "x": 1340, "y": 240, "config": {}}], "edges": [{"id": "s-m-next", "from": "s", "to": "m", "label": "", "outcome": "next"}, {"id": "m-nok-approved", "from": "m", "to": "nok", "label": "", "outcome": "approved"}, {"id": "m-nrej-rejected", "from": "m", "to": "nrej", "label": "", "outcome": "rejected"}, {"id": "nrej-rej-next", "from": "nrej", "to": "rej", "label": "", "outcome": "next"}, {"id": "nok-w-next", "from": "nok", "to": "w", "label": "", "outcome": "next"}, {"id": "w-rem-timeout", "from": "w", "to": "rem", "label": "", "outcome": "timeout"}, {"id": "rem-w-next", "from": "rem", "to": "w", "label": "", "outcome": "next"}, {"id": "w-h-next", "from": "w", "to": "h", "label": "Put on hold", "outcome": "next"}, {"id": "h-w-next", "from": "h", "to": "w", "label": "Resume", "outcome": "next"}, {"id": "w-done-next", "from": "w", "to": "done", "label": "Complete", "outcome": "next"}, {"id": "done-nd-next", "from": "done", "to": "nd", "label": "Finish", "outcome": "next"}, {"id": "nd-end-next", "from": "nd", "to": "end", "label": "", "outcome": "next"}]}'::jsonb, 'Preconfigured', 'System (preconfigured)', 'System (preconfigured)', 'System (preconfigured)', now()
FROM itsm_workflows w WHERE w.ticket_type = 'request' AND lower(w.name) = lower('Email / user ID creation (manager approval)') AND NOT EXISTS (SELECT 1 FROM itsm_workflow_versions v WHERE v.workflow_id = w.id);
